use std::process::Command;
use std::time::{Duration, Instant};

/// Generated files carry string literals with thousands of escape sequences, which
/// tree-sitter reports as thousands of children of one node. A walker that answers a
/// question about a node by rescanning its siblings is quadratic in that count: one
/// 1,174-line file took 30 seconds before this was fixed.
///
/// The bound is deliberately loose. It is not a benchmark — it is a tripwire for a
/// return to quadratic, which costs three orders of magnitude and clears any bound a
/// loaded CI machine could miss.
const BUDGET: Duration = Duration::from_secs(20);

fn scratch(name: &str) -> std::path::PathBuf {
    let dir = std::env::temp_dir().join(format!("rqx-perf-{name}"));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("a scratch directory");
    dir
}

fn scan(dir: &std::path::Path) -> (Duration, String) {
    let started = Instant::now();
    let output = Command::new(env!("CARGO_BIN_EXE_rqx"))
        .args(["scan"])
        .arg(dir)
        .args(["--reporter", "json", "--max-findings", "0"])
        .output()
        .expect("failed to run rqx");
    assert!(output.status.success(), "rqx exited with {}", output.status);
    (
        started.elapsed(),
        String::from_utf8(output.stdout).expect("output was not utf-8"),
    )
}

#[test]
fn a_string_literal_with_thousands_of_escapes_is_not_quadratic() {
    let dir = scratch("escapes");
    // 8,000 escape sequences in one literal, the shape of a generated schema blob.
    let literal = "line one\\n".repeat(20_000);
    std::fs::write(
        dir.join("generated-shape.ts"),
        format!("export const schema = \"{literal}\";\nexport const value = 1;\n"),
    )
    .expect("writing the fixture");

    let (elapsed, _) = scan(&dir);
    assert!(
        elapsed < BUDGET,
        "one string literal took {elapsed:?}, which means the walk went quadratic again"
    );
}

#[test]
fn a_generated_file_is_skipped_and_says_so() {
    let dir = scratch("generated");
    std::fs::write(
        dir.join("client.ts"),
        "/* This is code generated by Prisma. Do not edit directly. */\nexport const a = 1;\n",
    )
    .expect("writing");
    std::fs::write(dir.join("hand-written.ts"), "export const b = 2;\n").expect("writing");

    let (_, report) = scan(&dir);
    let summary = report.lines().last().expect("a summary line");
    assert!(
        summary.contains("\"files_scanned\":1"),
        "the generated file was still analysed: {summary}"
    );
    assert!(
        summary.contains("client.ts") && summary.contains("generated"),
        "a skipped file has to say why, or it is indistinguishable from a missing one: {summary}"
    );
}

fn summary_of(dir: &std::path::Path) -> serde_json::Value {
    let (_, report) = scan(dir);
    serde_json::from_str(report.lines().last().expect("a summary line")).expect("json")
}

fn write(dir: &std::path::Path, path: &str, text: &str) {
    let path = dir.join(path);
    std::fs::create_dir_all(path.parent().expect("a parent")).expect("a directory");
    std::fs::write(path, text).expect("writing");
}

#[test]
fn a_git_submodule_is_left_out_as_one_entry_unless_the_setting_brings_it_back() {
    let dir = scratch("submodule");
    write(
        &dir,
        ".gitmodules",
        "[submodule \"design\"]\n\tpath = design\n\turl = ../design.git\n",
    );
    write(&dir, "design/.git", "gitdir: ../.git/modules/design\n");
    write(&dir, "design/a.ts", "export const a = 1;\n");
    write(&dir, "design/nested/b.ts", "export const b = 2;\n");
    write(&dir, "app.ts", "export const app = 3;\n");

    let summary = summary_of(&dir);
    assert_eq!(summary["files_scanned"], 1, "{summary}");
    assert_eq!(
        summary["skipped_by"]["submodule"],
        serde_json::json!({ "files": 2, "paths": ["design"] }),
        "{summary}"
    );
    let skipped = summary["skipped"].as_array().expect("a list");
    assert_eq!(
        skipped.len(),
        1,
        "one entry for the whole submodule: {summary}"
    );
    assert!(
        skipped[0]
            .as_str()
            .is_some_and(|line| line.contains("design: a git submodule with 2 source files")),
        "{summary}"
    );

    write(&dir, "rqx.yaml", "scan:\n  skip_submodules: false\n");
    let summary = summary_of(&dir);
    assert_eq!(summary["files_scanned"], 3, "{summary}");
    assert_eq!(summary["skipped_by"], serde_json::json!({}), "{summary}");
}

#[test]
fn the_terminal_names_a_skipped_submodule_in_one_line() {
    let dir = scratch("submodule-footer");
    write(
        &dir,
        ".gitmodules",
        "[submodule \"design\"]\n\tpath = design\n",
    );
    write(&dir, "design/a.ts", "export const a = 1;\n");
    write(&dir, "app.ts", "export const app = 3;\n");

    let output = Command::new(env!("CARGO_BIN_EXE_rqx"))
        .args(["scan", "--no-tui", "--no-pager", "--color", "never"])
        .arg(&dir)
        .env("RQX_NO_UPDATE_CHECK", "1")
        .output()
        .expect("failed to run rqx");
    let text = String::from_utf8_lossy(&output.stdout);
    assert!(
        text.contains("skipped 1 file: 1 in submodule design/ \u{b7} -v lists them"),
        "{text}"
    );
}
